import{_ as a,I as t,c as n,o as r,j as o,J as s,a5 as l,a as d}from"./chunks/framework.CUJoMJm2.js";const f=JSON.parse('{"title":"ADR 001: Protocol Versioning & Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-protocol-versioning-and-compatibility.md","filePath":"adr/001-protocol-versioning-and-compatibility.md","lastUpdated":1768070912000}'),c={name:"adr/001-protocol-versioning-and-compatibility.md"};function p(m,e,u,h,g,b){const i=t("CopyOrDownloadAsMarkdownButtons");return r(),n("div",null,[e[0]||(e[0]=o("div",{style:{display:"none"},hidden:"true","aria-hidden":"true"},"Are you an LLM? You can read better optimized documentation at /adr/001-protocol-versioning-and-compatibility.md for this page in Markdown format",-1)),e[1]||(e[1]=o("h1",{id:"adr-001-protocol-versioning-compatibility",tabindex:"-1"},[d("ADR 001: Protocol Versioning & Compatibility "),o("a",{class:"header-anchor",href:"#adr-001-protocol-versioning-compatibility","aria-label":"Permalink to “ADR 001: Protocol Versioning & Compatibility”"},"​")],-1)),s(i),e[2]||(e[2]=l('<ul><li><strong>Date</strong>: 2025-11-22</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: SBP</li><li><strong>Tags</strong>: protocol, frames, handshake</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><ul><li><code>@sideband/protocol</code> is the foundation for all transports and runtimes. Breaking wire changes ripple through every package.</li><li>Current implementation encodes frames in a binary envelope with a JSON handshake. Version fields exist (<code>PROTOCOL_VERSION = &quot;1&quot;</code>) but policy was undocumented.</li><li>We need predictable rules for adding fields, handling unknown data, and reacting to version skew.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Version label: <code>&quot;sideband/1&quot;</code> (<code>PROTOCOL_ID</code>). Version is asserted during handshake; all frames on a connection share the same major version.</li><li>Negotiation: no downgrade/upgrade; v1 endpoints accept only <code>version === &quot;1&quot;</code> and <code>protocol === &quot;sideband&quot;</code>. Future negotiation, if needed, will happen via a new major version handshake.</li><li>Compatibility rules for v1: <ul><li>Additive only: new optional fields, new <code>ControlOp</code>, new capability strings are allowed without a major bump.</li><li>Unknown fields/caps/metadata MUST be ignored, not rejected.</li><li><strong>Frame header flags</strong> (byte 1): bit 0 signals timestamp presence; bits 1–7 reserved and must be zero. Non-zero reserved bits close the connection. See docs/protocols/sbp/wire-format.md.</li><li><strong>FrameId</strong> (16 bytes): opaque entropy with no semantic bits or structure. Decoders MUST treat as raw binary and MUST NOT interpret any bits. Validation is length-only (must be exactly 16 bytes).</li><li>Mandatory field changes (renames/removals) require a new major version.</li></ul></li><li>Error behavior on skew: <ul><li>If <code>protocol</code> or <code>version</code> is unsupported, send <code>ErrorFrame{code=UnsupportedVersion}</code> then close.</li><li>If a frame is malformed or uses a reserved bit/type, send <code>ErrorFrame{code=ProtocolViolation}</code> or <code>InvalidFrame</code> then close.</li></ul></li><li>Deprecation: v1 features may be deprecated via docs/caps but remain accepted until v2 exists; removal happens only in a new major version.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Implementations can evolve v1 by adding optional data without breaking peers.</li><li>Tests must include cases where unknown <code>caps</code>/metadata are ignored and reserved bits cause rejection.</li><li>Transports should surface version errors early (during handshake) to avoid partial session setup.</li><li><strong>v1 Timestamp Feature</strong>: Timestamps (flag bit 0) are an integrated v1 feature. All implementations MUST handle the timestamp bit, even if unused. Senders MAY include timestamps on any frame; receivers simply skip them if not used.</li><li>Future major versions will introduce a new handshake version string and may reuse the same framing with different semantics; coexistence requires either separate listeners or a negotiator shim.</li></ul>',7))])}const y=a(c,[["render",p]]);export{f as __pageData,y as default};
